{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MapleMonk.zouk_Customer_Calling_Report AS WITH CALLING AS ( SELECT * FROM ( SELECT Date_Created, CAST(Date_Created as Date) AS Call_Date, LTRIM(Customer_Number,\'0\') AS Customer_Number, Agent_Name, Leg2_Status, ROW_NUMBER() OVER ( PARTITION BY CAST(Date_Created as Date), LTRIM(Customer_Number,\'0\'), Agent_Name ORDER BY Date_Created DESC ) as row_num FROM MapleMonk.Zouk_Exotel_Calling_Report WHERE Upper(Agent_Name) like any (\'%MADHURI%\',\'%SHRUTHI%\') )where row_num = 1 ), Campaign AS ( SELECT SAFE.PARSE_DATE(\'%m/%d/%Y\', CAST(Calling_Date AS STRING)) AS Call_Date, TRIM(UPPER(Campaign_Name)) AS Campaign_Name, pickup_status, Agent_Name, RIGHT(REGEXP_REPLACE(CAST(Contact_Number AS STRING), r\'[^0-9]\', \'\'), 10) AS Phone_Number, SAFE_DIVIDE(100.0,COUNT(*) OVER (PARTITION BY SAFE.PARSE_DATE(\'%m/%d/%Y\', CAST(Calling_Date AS STRING)),Agent_Name)) AS Split_Target FROM MapleMonk.Zouk_CX_Customer_Calling_Sheet1 ), Orders AS ( SELECT SAFE_CAST(order_timestamp AS Date) AS Order_Date, Order_Name, Marketplace, order_status, REPLACE (phone,\'+91\',\'\') AS Shopify_Phone, discount_codes, SUM(Total_Sales) AS Total_Sales FROM MapleMonk.zouk_SHOPIFY_FACT_ITEMS WHERE order_status NOT LIKE \'%cancel%\' GROUP BY 1,2,3,4,5,6 ), First_Purchase_Logic AS ( SELECT cp.Call_Date, cp.Phone_Number, o.Order_Date, o.Order_name, CASE WHEN LOWER(o.Marketplace) LIKE \'shopify pos\' THEN \'OFFLINE\' ELSE \'ONLINE\' END AS Marketplace, o.Total_Sales, o.discount_codes, CASE WHEN LOWER(o.Order_Status) LIKE \'cancelled\' THEN \'Cancelled\' ELSE \'Fulfilled\' END AS Order_Status, DATE_DIFF(o.Order_Date, cp.Call_Date, DAY) as Days_to_Convert FROM Campaign cp INNER JOIN Orders o ON cp.Phone_Number = o.Shopify_Phone AND cp.Call_Date <= o.Order_Date QUALIFY ROW_NUMBER() OVER( PARTITION BY cp.Phone_Number ORDER BY o.Order_Date ASC ) = 1 ) SELECT cp.Call_Date, fp.Order_Date, cp.Campaign_Name, cp.Agent_Name, cp.Phone_Number, cp.pickup_status AS Call_Status, Marketplace as Channel, CASE WHEN fp.Order_Date IS NULL THEN NULL WHEN LOWER(fp.Marketplace) NOT LIKE \'shopify pos\' AND fp.Days_to_Convert <= 15 THEN \'CONSIDER\' WHEN LOWER(fp.Marketplace) LIKE \'shopify pos\' AND fp.Days_to_Convert <= 30 THEN \'CONSIDER\' ELSE \'NOT CONSIDERED\' END AS Consideration, fp.discount_codes AS Discount_Code, fp.Days_to_Convert, cp.Split_Target, fp.Order_name AS Order_ID, CASE WHEN LOWER(c.Leg2_Status) LIKE \'complete%\' THEN \'YES\' ELSE \'NO\' END AS Exotel_Found, Order_Status, COALESCE(fp.Total_Sales, 0) AS Total_Sales FROM Campaign cp LEFT JOIN Calling c ON cp.Phone_Number = c.Customer_Number AND cp.Call_Date = c.Call_Date AND cp.Agent_Name = c.Agent_Name LEFT JOIN First_Purchase_Logic fp ON cp.Phone_Number = fp.Phone_Number AND cp.Call_Date = fp.Call_Date",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            